val learningWireSerializers = SerializersModule {
    polymorphic(WirePersonalSyncEvent::class) {
        subclass(WirePersonalStreamEvent::class, WirePersonalStreamEvent.serializer())
        subclass(WirePersonalCheckpointEvent::class, WirePersonalCheckpointEvent.serializer())
        subclass(WirePersonalLessonEvent::class, WirePersonalLessonEvent.serializer())
        subclass(WirePersonalAttemptEvent::class, WirePersonalAttemptEvent.serializer())
        subclass(WirePersonalPlaybackObservationEvent::class, WirePersonalPlaybackObservationEvent.serializer())
        subclass(WirePersonalDialogueProgressEvent::class, WirePersonalDialogueProgressEvent.serializer())
    }
    polymorphic(WirePersonalReadRecord::class) {
        subclass(WirePersonalReadStream::class, WirePersonalReadStream.serializer())
        subclass(WirePersonalReadCheckpoint::class, WirePersonalReadCheckpoint.serializer())
        subclass(WirePersonalReadLesson::class, WirePersonalReadLesson.serializer())
        subclass(WirePersonalReadAttempt::class, WirePersonalReadAttempt.serializer())
        subclass(WirePersonalReadFeedback::class, WirePersonalReadFeedback.serializer())
        subclass(WirePersonalReadSelection::class, WirePersonalReadSelection.serializer())
        subclass(WirePersonalReadPlaybackRun::class, WirePersonalReadPlaybackRun.serializer())
        subclass(WirePersonalReadPlaybackObservation::class, WirePersonalReadPlaybackObservation.serializer())
        subclass(WirePersonalReadListeningCompletion::class, WirePersonalReadListeningCompletion.serializer())
        subclass(WirePersonalReadPracticePresentation::class, WirePersonalReadPracticePresentation.serializer())
        subclass(WirePersonalReadQuestionExampleExposure::class, WirePersonalReadQuestionExampleExposure.serializer())
    }
}
